const STOPWORDS = new Set(['the', 'a', 'an', 'and', 'or', 'but', 'is', 'am', 'are', 'was', 'were', 'be', 'been',
  'i', 'me', 'my', 'you', 'your', 'it', 'to', 'of', 'in', 'on', 'for', 'with', 'that', 'this', 'so', 'because',
  'have', 'has', 'had', 'do', 'does', 'did', 'just', 'really', 'very', 'about', 'at', 'as', 'like', 'feel',
  'feeling', 'feelings', 'today', 'right', 'now', 'hi', 'hey', 'hello', 'thanks', 'thank', 'please', 'yes',
  'no', 'ok', 'okay', 'sup', 'whats', 'yeah', 'yep', 'nah', 'good', 'fine', 'there', 'what', 'how', 'are']);

// Greetings / very short small talk that shouldn't get the full
// "it sounds like you're feeling X" treatment — that framing on a plain
// "hi" reads as robotic and, worse, repeats near-identically every time
// since there's no real content to reflect back.
const SMALL_TALK_PATTERNS = [
  /^h(i+|ey+|ello+)[.!]*$/i,
  /^(good\s?(morning|afternoon|evening|night))[.!]*$/i,
  /^(how are you|how's it going|hows it going|what's up|whats up|sup)[?.!]*$/i,
  /^(thanks|thank you|ty|okay|ok|k|cool|alright|got it|noted)[.!]*$/i,
  /^(yes|no|yeah|yep|nah|nope|sure)[.!]*$/i,
];

function isSmallTalk(message) {
  const trimmed = message.trim();
  if (SMALL_TALK_PATTERNS.some((p) => p.test(trimmed))) return true;
  // Very short, low-content messages (<=2 meaningful words) also count as
  // small talk rather than something requiring deep mood analysis.
  const meaningfulWordCount = trimmed
    .toLowerCase()
    .replace(/[^a-z0-9'\s]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w)).length;
  return meaningfulWordCount === 0 && trimmed.split(/\s+/).length <= 4;
}

/** A stronger string hash (FNV-1a variant) so nearby/short strings don't
 * collide the way a naive rolling sum can. `salt` lets us derive multiple
 * independent indices from the same message for different template slots
 * (opener, follow-up, mood line, suggestion) without them all moving in
 * lockstep. */
function hashIndex(str, mod, salt = '') {
  let h = 0x811c9dc5;
  const combined = `${salt}::${str}`;
  for (let i = 0; i < combined.length; i += 1) {
    h ^= combined.charCodeAt(i);
    h = Math.imul(h, 0x01000193); // Math.imul does correct 32-bit integer
    // multiplication; a plain `h * prime` here silently loses precision in
    // JS (doubles can't represent the full 32-bit product exactly), which
    // was collapsing almost every input to the same bucket.
  }
  return Math.abs(h) % mod;
}

/** Pull 1-2 salient content words out of the user's own message, so the
 * reply can reflect back something concrete instead of a generic template. */
function extractFocusWords(message) {
  const words = message
    .toLowerCase()
    .replace(/[^a-z0-9'\s]/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 3 && !STOPWORDS.has(w));
  const unique = [...new Set(words)].sort((a, b) => b.length - a.length);
  return unique.slice(0, 2);
}

function buildLocalReply({ personality, message, mood }) {
  const profile = PERSONALITY_PROFILES[personality] || PERSONALITY_PROFILES.warm_empathetic;

  // Light small-talk path: greetings/acknowledgements get a short, natural
  // reply instead of being forced through the full mood-analysis template.
  if (isSmallTalk(message)) {
    const idx = hashIndex(message, profile.smallTalk.length, `${personality}|smalltalk`);
    return profile.smallTalk[idx];
  }

  const safeMood = mood && MOOD_LINES[mood] ? mood : 'neutral';
  const moodLines = MOOD_LINES[safeMood];
  const suggestions = ACTIVITY_SUGGESTIONS[safeMood];

  const opener = profile.openers[hashIndex(message, profile.openers.length, `${personality}|opener`)];
  const followUp = profile.followUps[hashIndex(message, profile.followUps.length, `${personality}|followup`)];
  const moodLine = moodLines[hashIndex(message, moodLines.length, `${personality}|moodline`)];
  const suggestion = suggestions[hashIndex(message, suggestions.length, `${personality}|suggestion`)];

  const focusWords = extractFocusWords(message);
  const reflection = focusWords.length ? ` I noticed you mentioned "${focusWords.join(' / ')}" — ` : ' ';

  return `${opener} ${moodLine}${reflection}${followUp} ${suggestion}`.replace(/\s+/g, ' ').trim();
}

