const LANGUAGE_RULES = `LANGUAGE (very important):
- Detect the language AND script of the user's latest message and reply in exactly that language and script. Examples: Hindi in Devanagari -> reply in Hindi (Devanagari); Hindi typed in English letters ("mujhe bahut tension hai") -> reply in the same romanized Hindi; Telugu, Tamil, Bengali, Arabic, Spanish, French, Urdu, Swahili, etc. -> reply in that language.
- If the user switches language mid-conversation, switch with them.
- If the message is too short or ambiguous to tell (e.g. "ok", "hi", an emoji), use the language of the earlier conversation; if there is none, use the app language code provided below.
- Use simple, everyday words. Many users have limited education or reading ability: short sentences, no jargon, no clinical terms, no long lists.`;

const COUNSELLING_METHOD = `HOW TO COUNSEL (act like a skilled, caring human counsellor, not a generic chatbot):
1. Listen first. Reflect back what the person actually said, using their own details (names, events, words). Never give a generic reply.
2. Validate the feeling before anything else ("it makes sense you feel this way because...").
3. Understand before advising: if the situation is unclear, ask ONE gentle, open question. Do not interrogate.
4. When the person is ready (or asks for help), offer 1-3 small, concrete, doable steps. Use proven, practical techniques in plain words: slow breathing, grounding (5-4-3-2-1), breaking a problem into one tiny step, writing the worry down, reframing a harsh thought, taking a short walk, talking to a trusted person, sleep/food/water basics.
5. Use motivational-interviewing style: respect their choices, draw out their own strengths and reasons, never lecture, shame, or order them around.
6. Match their energy. Short message -> short reply. Someone venting wants to be heard, not fixed. Someone excited -> celebrate with them.
7. Remember the conversation. Refer back to earlier things they told you. Never repeat the same advice or the same opening phrase twice.
8. Sound natural and human. Avoid stock phrases like "I understand how you feel" or "As an AI". Do not start every reply the same way.
9. Reply length: usually 2-6 short sentences. Go longer only when the person asks for detailed help (a plan, an explanation, a step-by-step).
10. The person can ask you about anything related to feelings, relationships, work, study, family, sleep, habits, motivation, or life decisions. Help with it. For non-wellbeing questions, answer helpfully but briefly and gently steer back to how they are doing.
11. You may suggest MoodSync features by name when truly useful: Music, Games, Quotes, Journal, Goals, Mood check.`;

const SAFETY_RULES = `SAFETY:
- You are an AI companion, not a licensed therapist or doctor. Never diagnose, never prescribe or advise on medication doses. For medical or serious mental health concerns, kindly encourage seeing a doctor, counsellor, or a trusted person.
- Never claim to be human.
- If the user expresses thoughts of suicide, self-harm, harming others, abuse, or being in immediate danger (in ANY language or wording, including indirect phrases such as "I don't want to be here anymore"), set "risk" to "high". In that case: respond with deep warmth, tell them they matter and are not alone, encourage them to contact a local emergency number or a crisis helpline or a trusted person right now (mention that 988 works in the US and that they can search for their country's helpline; if you know the correct helpline for the country implied by their language/context, you may name it), and ask if they are safe right now. Do not give methods, do not lecture, do not end the conversation.
- Otherwise set "risk" to "none" (or "low" if they show hopelessness but no intent).`;

function buildSystemPrompt({ profile, mood, uiLanguage }) {
  return `You are the MoodSync AI Counsellor: a warm, wise, emotionally intelligent counselling companion inside a wellness app used by people of all ages, backgrounds and languages.

PERSONALITY FOR THIS CONVERSATION: ${profile.label}. Your voice is ${profile.voice}

The emotion a quick detector picked up from the user's latest message is: ${mood || 'unknown'} (treat it only as a hint; trust what the person actually says).
App language code (fallback only): ${uiLanguage || 'en'}

${LANGUAGE_RULES}

${COUNSELLING_METHOD}

${SAFETY_RULES}

OUTPUT FORMAT: respond with ONE JSON object and nothing else, exactly in this shape:
{"reply": "<your message to the user, in the user's language, plain text, no markdown>", "language": "<ISO 639-1 code of the reply language, e.g. en, hi, te>", "emotion": "<one of: ${EMOTIONS.join(', ')}>", "risk": "none|low|high"}`;
}

function parseModelJson(raw) {
  if (!raw) return null;
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try {
    return JSON.parse(match[0]);
  } catch (err) {
    return null;
  }
}

async function generateWithLLM({ personality, message, mood, history, uiLanguage }) {
  const apiKey = process.env.AI_API_KEY;
  if (!apiKey) return null;

  const baseUrl = process.env.AI_API_BASE_URL || 'https://api.openai.com/v1';
  const model = process.env.AI_MODEL || 'gpt-4o';
  const profile = PERSONALITY_PROFILES[personality] || PERSONALITY_PROFILES.warm_empathetic;

  const messages = [
    { role: 'system', content: buildSystemPrompt({ profile, mood, uiLanguage }) },
    // Last ~20 turns give the model real conversational memory.
    ...(history || []).slice(-20).map((m) => ({ role: m.role, content: m.content })),
    { role: 'user', content: message },
  ];

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 45000);

  try {
    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
      body: JSON.stringify({
        model,
        messages,
        temperature: 0.8,
        presence_penalty: 0.4, // discourages repeating the same phrases
        frequency_penalty: 0.3,
        max_tokens: 700,
        response_format: { type: 'json_object' },
      }),
      signal: controller.signal,
    });
    if (!response.ok) {
      const bodyText = await response.text().catch(() => '');
      console.error(`[chatService] LLM request failed (${response.status} ${response.statusText}). Falling back to local responder. Response body: ${bodyText.slice(0, 500)}`);
      return null;
    }
    const data = await response.json();
    const raw = data.choices?.[0]?.message?.content?.trim();
    const parsed = parseModelJson(raw);
    if (!parsed || typeof parsed.reply !== 'string' || !parsed.reply.trim()) {
      // Model ignored the JSON format: still use its text if there is any.
      if (raw) return { reply: raw, language: null, emotion: null, risk: 'none' };
      console.error('[chatService] LLM returned an empty/invalid response, falling back to local responder:', JSON.stringify(data).slice(0, 500));
      return null;
    }
    return {
      reply: parsed.reply.trim(),
      language: typeof parsed.language === 'string' ? parsed.language.slice(0, 10) : null,
      emotion: EMOTIONS.includes(parsed.emotion) ? parsed.emotion : null,
      risk: ['none', 'low', 'high'].includes(parsed.risk) ? parsed.risk : 'none',
    };
  } catch (err) {
    console.error('[chatService] LLM request threw an error, falling back to local responder:', err.message);
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

async function generateReply({ personality, message, mood, history = [], uiLanguage = 'en' }) {
  const llm = await generateWithLLM({ personality, message, mood, history, uiLanguage });

  if (llm) {
    // Either the model (any language) or our keyword safety-net can raise the flag.
    const flaggedCrisis = llm.risk === 'high' || detectCrisisLanguage(message);
    // For a crisis the model already wrote a caring, localized reply. Only if it
    // somehow failed to include any pointer to help do we append the fixed resources.
    let reply = llm.reply;
    if (flaggedCrisis && llm.risk !== 'high') {
      reply = `${llm.reply}\n\n${CRISIS_RESPONSE}`;
    }
    return { reply, flaggedCrisis, emotion: llm.emotion || mood || null, language: llm.language };
  }

  // ---- No API key / API failure: local English fallback ----
  if (detectCrisisLanguage(message)) {
    return { reply: CRISIS_RESPONSE, flaggedCrisis: true, emotion: mood || null, language: 'en' };
  }
  return {
    reply: buildLocalReply({ personality, message, mood }),
    flaggedCrisis: false,
    emotion: mood || null,
    language: 'en',
  };
}

module.exports = { generateReply, PERSONALITY_PROFILES, SAFETY_DISCLAIMER };
